class Solution {
public:
    int minLength(std::string s) {
        std::string st;
        for (char c : s) {
            if (!st.empty() && ((st.back() == 'A' && c == 'B') || (st.back() == 'C' && c == 'D'))) {
                st.pop_back();
            } else {
                st.push_back(c);
            }
        }
        return st.size();
    }
};

class Solution {
    public int minLength(String s) {
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            int len = sb.length();
            if (len > 0 && ((sb.charAt(len - 1) == 'A' && c == 'B') || (sb.charAt(len - 1) == 'C' && c == 'D'))) {
                sb.deleteCharAt(len - 1);
            } else {
                sb.append(c);
            }
        }
        return sb.length();
    }
}

var minLength = function(s) {
    const st = [];
    for (const c of s) {
        if (st.length > 0 && ((st[st.length - 1] === 'A' && c === 'B') || (st[st.length - 1] === 'C' && c === 'D'))) {
            st.pop();
        } else {
            st.push(c);
        }
    }
    return st.length;
};
